"""Authenticated loopback task-control dashboard shell."""

from __future__ import annotations

from pathlib import Path


_BRAND_ASSET_ROOT = Path(__file__).with_name("assets")
_FORBIDDEN_SVG_MARKERS = (
    "<script",
    "javascript:",
    "<foreignobject",
    "<image",
    "xlink:href",
    " onload=",
    " onclick=",
    "http://",
    "https://",
    "<!entity",
)


def _inline_audited_wordmark() -> str:
    """Return the local path-only wordmark as inert inline SVG."""

    try:
        wordmark = (_BRAND_ASSET_ROOT / "tweebit-wordmark.svg").read_text(
            encoding="utf-8"
        )
    except OSError:
        return ""
    normalized = wordmark.lower()
    security_scan = normalized.replace(
        'xmlns="http://www.w3.org/2000/svg"', ""
    )
    if not normalized.lstrip().startswith("<svg") or any(
        marker in security_scan for marker in _FORBIDDEN_SVG_MARKERS
    ):
        return ""
    return wordmark.replace(
        "<svg ",
        '<svg class="brand-wordmark" aria-hidden="true" focusable="false" ',
        1,
    )


